<?php
/** TEMP PS S1685 mn — DEPLOY pataisa: petshop-pakartoti.php + refill-pakartoti.php (data lietuviškai, prekės pavadinimas nekartojamas); bak, token_get_all, heartbeat, rollback. */
add_action('init', function(){
  if (!isset($_GET['ps_s1685mn'])) return; $o=array('v'=>'S1685 mn'); $f=WPMU_PLUGIN_DIR.'/petshop-pakartoti.php'; $t=WPMU_PLUGIN_DIR.'/ps-sablonai/refill-pakartoti.php'; $bd=WP_CONTENT_DIR.'/uploads/ps-backups';
  copy($f,$bd.'/petshop-pakartoti.php.bak_s1685'); copy($t,$bd.'/refill-pakartoti.php.bak_s1685');
  $np=base64_decode(''); $nt=base64_decode(''); if(md5($np)!=='9916c1adef48332df918d7f222e7b93f'||md5($nt)!=='aa1ab20a777af38886bb337073bf36d4'){ $o['STOP']='md5 payload'; echo json_encode($o); exit; }
  try { token_get_all($np, TOKEN_PARSE); token_get_all($nt, TOKEN_PARSE); } catch (Throwable $e) { $o['STOP']='ParseError: '.$e->getMessage(); echo json_encode($o); exit; }
  file_put_contents($t,$nt); file_put_contents($f,$np); if(function_exists('opcache_invalidate')){ opcache_invalidate($f,true); opcache_invalidate($t,true); } $o['md5']=array(md5_file($f),md5_file($t));
  $hb=wp_remote_get(home_url('/'),array('timeout'=>20,'sslverify'=>false)); $code=is_wp_error($hb)?0:wp_remote_retrieve_response_code($hb); $o['heartbeat']=$code; if($code>=500||$code===0){ copy($bd.'/petshop-pakartoti.php.bak_s1685',$f); copy($bd.'/refill-pakartoti.php.bak_s1685',$t); $o['ROLLBACK']='bak'; }
  header('Content-Type: application/json; charset=utf-8'); echo json_encode($o,JSON_UNESCAPED_UNICODE); exit;
});
